from enum import Enum

class Mode(Enum):
    SAFE = 'safe'
    IDLE = 'idle'
    NOMINAL = 'nominal'
    SCIENCE = 'science'

class FlightModeMachine:
    def __init__(self, mode=Mode.IDLE):
        self.mode = mode

    def transition(self, target, *, battery_ok=False, attitude_valid=False, ground_release=False):
        if self.mode is Mode.SAFE:
            if target is Mode.IDLE and ground_release:
                self.mode = Mode.IDLE
                return True
            return False
        if self.mode is Mode.IDLE and target is Mode.NOMINAL and battery_ok and attitude_valid:
            self.mode = Mode.NOMINAL
            return True
        if self.mode is Mode.NOMINAL and target is Mode.SCIENCE and attitude_valid:
            self.mode = Mode.SCIENCE
            return True
        return False
